INSERT INTO `news` VALUES (_binary '�N:�<sn�\r�h�dL','Lựa chọn thước đo khoảng cách như thế nào cho đúng','<p>Mỗi chiếc thước dù là dây hay lá thì đều được khắc theo 1 tiêu chuẩn nhưng vạch khắc độ nét, tính đồng bộ, khả năng ứng dụng thì đều cần người vận hành kết nối điểm dấu tới điểm đo</p>\n<p>Với sự phát triển của thiết bị điện tử, hiện nay thước đo laser cầm tay đáp ứng được yêu cầu khắt khe của tiêu chuẩn đo lường như: tính ổn định chính xác bởi chùm tia phản xạ từ máy được phát ra và thu hồi ngay lập tức, thao tác nhanh gọn bấm nút có kết quả ngay</p>\n<p>Tiết kiệm chi phí vận hành, giờ đây không cần người kéo thước, chỉ cần đặt máy nhắm tới vị trí cần đo là có ngay kết quả, hầu như không hao mòn vật lý, mất vạch chia như thước lá phổ thông. </p>\n<p>Tiết kiệm thời gian khi lưu được 20 kết quả đo trước đó, dễ dàng thực nghiệm đo nhanh và bàn giao kết quả</p>\n<p><!-- SEO META TAGS --></p>\n<p><!-- OPEN GRAPH (FACEBOOK & ZALO SHARING) --></p>\n<p><!-- SCHEMA CHUẨN GOOGLE (PRODUCT & FAQ) --></p>\n<article class=\"product-content-wrap\" style=\"font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 900px; margin: auto; padding: 15px;\"><!-- PHẦN HEADER BÀI VIẾT CHUẨN H1 --><header>\n<h1 style=\"color: #0b5ed7; font-size: 24px; border-bottom: 2px solid #0b5ed7; padding-bottom: 10px;\">Máy Đo Khoảng Cách Laser Cầm Tay CEM LDM-100H (100m) – Đo Nhanh, Chuẩn Xác, Bền Bỉ</h1>\n<p style=\"font-size: 15px; color: #555;\">Thời kỳ kéo thước cuộn chùng dây, mòn vạch khắc đã qua. <strong>CEM LDM-100H</strong> mang đến giải pháp đo đạc hiện đại: chỉ cần một người thao tác, phát tia laser nhắm mục tiêu là có kết quả chuẩn milimet sau 0.5 giây.</p>\n</header><!-- LÝ DO NÊN CHỌN SẢN PHẨM -->\n<section style=\"margin-top: 25px;\">\n<h2 style=\"font-size: 19px; color: #222; border-left: 4px solid #0b5ed7; padding-left: 10px;\">Tại Sao CEM LDM-100H Là Trợ Thủ Đắc Lực Cho Kỹ Sư &amp; Thợ Thi Công?</h2>\n<ul style=\"padding-left: 20px;\">\n<li style=\"margin-bottom: 8px;\"><strong>Dải đo rộng đến 100m:</strong> Phù hợp cho cả công tác hoàn thiện nội thất trong nhà lẫn khảo sát mặt bằng, cảnh quan, xưởng công nghiệp ngoài trời.</li>\n<li style=\"margin-bottom: 8px;\"><strong>Độ chính xác cao ±1.5 mm:</strong> Nguyên lý phản xạ quang học triệt tiêu sai số võng thước dây truyền thống.</li>\n<li style=\"margin-bottom: 8px;\"><strong>Đa năng toàn diện:</strong> Đo khoảng cách liên tục (tracking), tự động tính diện tích (m²), thể tích (m³) và đo gián tiếp chiều cao vật cản theo định lý Pythagoras.</li>\n<li style=\"margin-bottom: 8px;\"><strong>Bộ nhớ lưu 20 kết quả:</strong> Thoải mái đo quét cả phòng rồi mới ghi chép, tiết kiệm hơn 50% thời gian nghiệm thu công trình.</li>\n<li style=\"margin-bottom: 8px;\"><strong>Kháng nước bụi IP54:</strong> Vỏ máy bọc cao su chống va đập, hạn chế bụi bẩn và tia nước bắn tóe tại công trường.</li>\n</ul>\n</section>\n<!-- BẢNG THÔNG SỐ KỸ THUẬT -->\n<section style=\"margin-top: 30px;\">\n<h2 style=\"font-size: 19px; color: #222; border-left: 4px solid #0b5ed7; padding-left: 10px;\">Thông Số Kỹ Thuật Chi Tiết CEM LDM-100H</h2>\n<table style=\"width: 100%; border-collapse: collapse; margin-top: 12px; font-size: 14px;\">\n<thead>\n<tr style=\"background-color: #0b5ed7; color: #fff;\">\n<th style=\"padding: 10px; border: 1px solid #dee2e6; text-align: left; width: 35%;\">Thông số</th>\n<th style=\"padding: 10px; border: 1px solid #dee2e6; text-align: left;\">Giá trị thực tế</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Phạm vi đo</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">0.05 m – 100 m</td>\n</tr>\n<tr style=\"background-color: #f8f9fa;\">\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Độ chính xác</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">±1.5 mm</td>\n</tr>\n<tr>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Đơn vị hiển thị</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">m, in, ft (Độ phân giải 1 mm)</td>\n</tr>\n<tr style=\"background-color: #f8f9fa;\">\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Tiêu chuẩn Laser</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">Class II, 635 nm, công suất &lt; 1 mW</td>\n</tr>\n<tr>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Bộ nhớ trong</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">Lưu 20 kết quả đo gần nhất</td>\n</tr>\n<tr style=\"background-color: #f8f9fa;\">\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Cấp độ bảo vệ</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">IP54 (Chống bụi và nước bắn tóe)</td>\n</tr>\n<tr>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Nguồn cấp &amp; Thời lượng</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">2 pin AAA 1.5V (lên tới 4.000 lần đo)</td>\n</tr>\n<tr style=\"background-color: #f8f9fa;\">\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Tự động ngắt nguồn</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">Laser tắt sau 30s | Máy tắt sau 3 phút</td>\n</tr>\n<tr>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6; font-weight: bold;\">Kích thước &amp; Trọng lượng</td>\n<td style=\"padding: 8px 10px; border: 1px solid #dee2e6;\">115 x 48 x 28 mm / ~135 g</td>\n</tr>\n</tbody>\n</table>\n</section>\n<!-- ỨNG DỤNG THỰC TẾ -->\n<section style=\"margin-top: 30px;\">\n<h2 style=\"font-size: 19px; color: #222; border-left: 4px solid #0b5ed7; padding-left: 10px;\">Ứng Dụng Thực Tế Theo Ngành Nghề</h2>\n<ul style=\"padding-left: 20px;\">\n<li style=\"margin-bottom: 8px;\"><strong>Thi công nội thất &amp; Quảng cáo:</strong> Đo kích thước tường, cửa kính, trần thạch cao, chiều cao biển hiệu từ xa mà không cần trèo thang.</li>\n<li style=\"margin-bottom: 8px;\"><strong>Giám sát xây dựng &amp; Cơ điện (M&amp;E):</strong> Đo chiều dài ống thông gió, tuyến máng cáp, kiểm tra độ võng và diện tích mặt sàn đổ bê tông.</li>\n<li style=\"margin-bottom: 8px;\"><strong>Môi giới &amp; Thẩm định Bất động sản:</strong> Tính nhanh diện tích căn hộ, nhà xưởng thực tế để lập hồ sơ khách hàng minh bạch.</li>\n</ul>\n</section>\n<!-- CÂU HỎI THƯỜNG GẶP (FAQ) -->\n<section style=\"margin-top: 30px; background: #fdfdfd; border: 1px solid #eee; border-radius: 6px; padding: 15px;\">\n<h2 style=\"font-size: 19px; color: #222; margin-top: 0;\">Câu Hỏi Thường Gặp (FAQ)</h2>\n<div style=\"margin-bottom: 12px;\">\n<p style=\"font-weight: bold; margin-bottom: 4px;\">1. Máy đo khoảng cách laser CEM LDM-100H đo được tối đa bao xa?</p>\n<p style=\"margin: 0; color: #555;\">Máy đo được cự ly tối đa 100m với độ chính xác đạt ±1.5mm.</p>\n</div>\n<div>\n<p style=\"font-weight: bold; margin-bottom: 4px;\">2. Bộ sản phẩm tiêu chuẩn gồm những gì?</p>\n<p style=\"margin: 0; color: #555;\">Trọn bộ bao gồm: Thân máy CEM LDM-100H, 02 pin AAA, bao đựng đeo hông, dây đeo tay và sách hướng dẫn sử dụng.</p>\n</div>\n</section>\n</article>\n<p>Dưới đây là video</p>\n<p><iframe title=\"Máy đo laser cầm tay Cem LDM-100H\" src=\"https://www.youtube.com/embed/gLM2LgDYnC8\" width=\"560\" height=\"315\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" allowfullscreen=\"allowfullscreen\" referrerpolicy=\"strict-origin-when-cross-origin\"></iframe></p>\n<div>\n<div> </div>\n</div>','Tống Phú Quang','published','Lựa chọn thước đo khoảng cách như thế nào cho đúng',NULL,'lua-cho-thuoc-do-khoang-cach-the-nao-cho-dung','news','2026-10-18 08:57:02.012214','2026-10-18 09:12:51.893750',NULL),(_binary '�^\�.~H�M\�^\�\"��','Cách chọn máy định vị GNSS RTK phù hợp nhu cầu','<p>Máy định vị GNSS RTK là khoản đầu tư lớn, nên việc chọn đúng cấu hình giúp tiết kiệm chi phí và đáp ứng tốt công việc khảo sát.</p><h4>Nội dung chính</h4><ul><li>Xác định rõ loại công việc: khảo sát địa hình, đo đạc địa chính, bố trí công trình hay san lấp.</li><li>Ưu tiên thiết bị có bù nghiêng IMU nếu thường xuyên đo điểm khó, điểm che khuất.</li><li>Kiểm tra khả năng kết nối 4G, radio UHF và phần mềm khảo sát đi kèm.</li><li>Cân nhắc độ bền IP67/IP68 và thời lượng pin cho điều kiện ngoài hiện trường.</li></ul><p>Liên hệ Thiên Phú để được tư vấn cấu hình GNSS RTK phù hợp với nhu cầu và ngân sách.</p>','Tống Phú Quang','published','Cách chọn máy định vị GNSS RTK phù hợp nhu cầu','Hướng dẫn chọn máy định vị GNSS RTK theo công việc, độ chính xác, bù nghiêng IMU, kết nối và độ bền.','cach-chon-may-dinh-vi-gnss-rtk-phu-hop-nhu-cau','news','2026-10-21 14:25:19.382893','2026-10-21 14:25:19.382893',NULL),(_binary '�^\�.Aq��a��:�','Máy toàn đạc điện tử là gì? Khi nào nên dùng?','<p>Máy toàn đạc điện tử là thiết bị đo góc và đo cạnh chính xác, được sử dụng rộng rãi trong khảo sát, xây dựng và đo đạc bản đồ.</p><h4>Nội dung chính</h4><ul><li>Đo góc, đo cạnh và đo cao trong cùng một thiết bị.</li><li>Đo không gương cho phép đo tới điểm khó tiếp cận.</li><li>Phù hợp bố trí tim trục, đo hoàn công và kiểm tra công trình.</li><li>Nên chọn độ chính xác 2 giây cho công trình yêu cầu cao, 5 giây cho công việc thông thường.</li></ul><p>Thiên Phú cung cấp máy toàn đạc chính hãng kèm hướng dẫn sử dụng và bảo hành.</p>','Tống Phú Quang','published','Máy toàn đạc điện tử là gì? Khi nào nên dùng?','Tìm hiểu máy toàn đạc điện tử, khả năng đo góc, đo cạnh, đo không gương và ứng dụng trong xây dựng.','may-toan-dac-dien-tu-la-gi-khi-nao-nen-dung','news','2026-10-21 14:25:19.426120','2026-10-21 14:25:19.426120',NULL),(_binary '�^\�.\\qߥ�\Z��|�\�','Hướng dẫn sử dụng máy thủy bình đúng cách','<p>Máy thủy bình cho kết quả chính xác nếu được thiết lập và thao tác đúng. Dưới đây là các bước cơ bản khi sử dụng ngoài hiện trường.</p><h4>Nội dung chính</h4><ul><li>Cân bằng máy bằng 3 ốc cân, kiểm tra bọt thủy tròn trước khi đo.</li><li>Đặt mia thẳng đứng và đọc số tại vạch giữa để hạn chế sai số.</li><li>Kiểm tra khoảng cách từ máy tới mia, tránh vượt quá phạm vi khuyến nghị.</li><li>Bảo quản máy nơi khô ráo, vệ sinh ống kính sau mỗi buổi đo.</li></ul><p>Nếu cần hỗ trợ kỹ thuật hoặc chọn máy thủy bình, hãy liên hệ Thiên Phú.</p>','Tống Phú Quang','published','Hướng dẫn sử dụng máy thủy bình đúng cách','Các bước sử dụng máy thủy bình đúng cách: cân bằng máy, đặt mia, đọc số và bảo quản thiết bị.','huong-dan-su-dung-may-thuy-binh-dung-cach','news','2026-10-21 14:25:19.452117','2026-10-21 14:25:19.452117',NULL),(_binary '�^\�.xyr�\�\�)!\�{�','So sánh máy đo khoảng cách laser và thước cuộn truyền thống','<p>Máy đo khoảng cách laser ngày càng phổ biến nhờ tốc độ và độ chính xác vượt trội so với thước cuộn trong nhiều tình huống.</p><h4>Nội dung chính</h4><ul><li>Đo một mình nhanh chóng ở khoảng cách xa, không cần người giữ đầu dây.</li><li>Sai số chỉ vài milimet, hỗ trợ đo diện tích và thể tích.</li><li>Thước cuộn phù hợp đo ngắn, không cần pin, chi phí thấp.</li><li>Máy laser phù hợp công trình, nội thất và đo đạc trong nhà.</li></ul><p>Thiên Phú cung cấp máy đo khoảng cách laser chính hãng từ SNDWAY, LAISAI, Leica.</p>','Tống Phú Quang','published','So sánh máy đo khoảng cách laser và thước cuộn','So sánh ưu nhược điểm của máy đo khoảng cách laser và thước cuộn để chọn dụng cụ phù hợp.','so-sanh-may-do-khoang-cach-laser-va-thuoc-cuon','news','2026-10-21 14:25:19.480591','2026-10-21 14:25:19.480591',NULL),(_binary '�^\�.�tm�(\n�\��c','Bù nghiêng IMU trên máy GNSS RTK hoạt động thế nào?','<p>Bù nghiêng IMU giúp máy GNSS RTK xác định điểm đo ngay cả khi sào không dựng thẳng đứng, tiết kiệm thời gian ngoài hiện trường.</p><h4>Nội dung chính</h4><ul><li>Cảm biến IMU đo góc nghiêng của sào theo thời gian thực.</li><li>Phần mềm tính toán vị trí điểm đo dựa trên góc nghiêng và chiều cao sào.</li><li>Giảm thao tác cân bằng, tăng năng suất khi đo điểm khó.</li><li>Cần hiệu chuẩn IMU định kỳ để đảm bảo độ chính xác.</li></ul><p>Các dòng GNSS RTK tại Thiên Phú đều được kiểm tra IMU trước khi bàn giao.</p>','Tống Phú Quang','published','Bù nghiêng IMU trên máy GNSS RTK hoạt động thế nào?','Tìm hiểu nguyên lý bù nghiêng IMU trên máy GNSS RTK và cách hiệu chuẩn để đảm bảo độ chính xác.','bu-nghieng-imu-tren-may-gnss-rtk-hoat-dong-the-nao','news','2026-10-21 14:25:19.504277','2026-10-21 14:25:19.504277',NULL),(_binary '�^\�.�w5�o�\'\�j\�^','Kinh nghiệm chọn máy toàn đạc cho công trình xây dựng','<p>Mỗi công trình có yêu cầu đo đạc khác nhau, vì vậy chọn máy toàn đạc cần dựa trên độ chính xác, phạm vi đo và điều kiện thi công.</p><h4>Nội dung chính</h4><ul><li>Công trình dân dụng thường dùng máy 5 giây, công trình hạ tầng cần 2 giây.</li><li>Đo không gương xa giúp bố trí điểm trên cao hoặc khu vực nguy hiểm.</li><li>Ưu tiên máy có bộ nhớ lớn và kết nối Bluetooth để xuất dữ liệu.</li><li>Kiểm tra chế độ bảo hành và dịch vụ hiệu chuẩn sau bán hàng.</li></ul><p>Đội ngũ Thiên Phú sẵn sàng tư vấn máy toàn đạc theo từng loại công trình.</p>','Tống Phú Quang','published','Kinh nghiệm chọn máy toàn đạc cho công trình xây dựng','Kinh nghiệm chọn máy toàn đạc theo độ chính xác, phạm vi đo, kết nối và dịch vụ sau bán hàng.','kinh-nghiem-chon-may-toan-dac-cho-cong-trinh-xay-dung','news','2026-10-21 14:25:19.529451','2026-10-21 14:25:19.529451',NULL),(_binary '�^\�.\�p��\�n�$i�','Quy trình đo đạc địa chính bằng GNSS RTK','<p>GNSS RTK giúp đo đạc địa chính nhanh và chính xác nếu thực hiện đúng quy trình từ chuẩn bị đến nghiệm thu dữ liệu.</p><h4>Nội dung chính</h4><ul><li>Thu thập thông tin thửa đất, mốc giới và hệ tọa độ trước khi đo.</li><li>Thiết lập trạm base hoặc kết nối CORS ổn định.</li><li>Đo kiểm tra điểm khống chế và lưu dữ liệu theo từng thửa.</li><li>Xuất dữ liệu, đối chiếu bản đồ và kiểm tra sai số trước khi nộp.</li></ul><p>Thiên Phú hỗ trợ tư vấn thiết bị và quy trình đo đạc địa chính bằng GNSS RTK.</p>','Tống Phú Quang','published','Quy trình đo đạc địa chính bằng GNSS RTK','Quy trình đo đạc địa chính bằng GNSS RTK từ chuẩn bị dữ liệu, thiết lập trạm đến nghiệm thu kết quả.','quy-trinh-do-dac-dia-chinh-bang-gnss-rtk','news','2026-10-21 14:25:19.554044','2026-10-21 14:25:19.554044',NULL),(_binary '�^\�.\�w\�\���n�','Những lỗi thường gặp khi sử dụng máy thủy bình','<p>Nhiều sai số khi đo cao không đến từ thiết bị mà từ thao tác chưa đúng. Dưới đây là những lỗi phổ biến cần tránh.</p><h4>Nội dung chính</h4><ul><li>Không cân bằng máy kỹ trước khi đọc số.</li><li>Đặt mia nghiêng hoặc đặt trên nền không chắc chắn.</li><li>Đo ở khoảng cách quá xa hoặc trong điều kiện rung lắc mạnh.</li><li>Không kiểm tra sai số hệ thống định kỳ.</li></ul><p>Thiên Phú cung cấp dịch vụ kiểm tra, hiệu chuẩn máy thủy bình định kỳ.</p>','Tống Phú Quang','published','Những lỗi thường gặp khi sử dụng máy thủy bình','Các lỗi phổ biến khi sử dụng máy thủy bình và cách khắc phục để đảm bảo kết quả đo chính xác.','nhung-loi-thuong-gap-khi-su-dung-may-thuy-binh','news','2026-10-21 14:25:19.578495','2026-10-21 14:25:19.578495',NULL),(_binary '�^\�.�z�>�\�H\�y','Cách bảo quản thiết bị trắc địa mùa mưa','<p>Mùa mưa là thời điểm thiết bị trắc địa dễ gặp sự cố ẩm, gỉ và hỏng linh kiện nếu không được bảo quản đúng cách.</p><h4>Nội dung chính</h4><ul><li>Lau khô máy và phụ kiện ngay sau khi sử dụng.</li><li>Tháo pin nếu không dùng trong thời gian dài.</li><li>Bảo quản trong vali chống ẩm, kèm gói hút ẩm.</li><li>Kiểm tra ống kính, chân máy và cáp sạc định kỳ.</li></ul><p>Liên hệ Thiên Phú nếu thiết bị có dấu hiệu ẩm hoặc hoạt động bất thường.</p>','Tống Phú Quang','published','Cách bảo quản thiết bị trắc địa mùa mưa','Hướng dẫn bảo quản máy GNSS, máy toàn đạc và máy thủy bình trong mùa mưa để tránh ẩm, gỉ.','cach-bao-quan-thiet-bi-trac-dia-mua-mua','news','2026-10-21 14:25:19.603631','2026-10-21 14:25:19.603631',NULL),(_binary '�^\�/tH���\�\�4','Phân biệt máy toàn đạc và máy kinh vĩ','<p>Máy toàn đạc và máy kinh vĩ đều đo góc, nhưng khác nhau về khả năng đo cạnh và ứng dụng thực tế.</p><h4>Nội dung chính</h4><ul><li>Máy kinh vĩ chỉ đo góc, thường dùng trong bố trí cơ bản.</li><li>Máy toàn đạc tích hợp đo góc, đo cạnh và xử lý dữ liệu.</li><li>Máy toàn đạc phù hợp khảo sát, hoàn công và đo đạc bản đồ.</li><li>Máy kinh vĩ có chi phí thấp hơn nhưng ứng dụng hẹp hơn.</li></ul><p>Thiên Phú tư vấn lựa chọn thiết bị phù hợp với từng nhu cầu đo đạc.</p>','Tống Phú Quang','published','Phân biệt máy toàn đạc và máy kinh vĩ','So sánh máy toàn đạc và máy kinh vĩ về chức năng, ứng dụng và chi phí để chọn thiết bị phù hợp.','phan-biet-may-toan-dac-va-may-kinh-vi','news','2026-10-21 14:25:19.628268','2026-10-21 14:25:19.628268',NULL),(_binary '�^\�/!~U��\��\�n\�','Vai trò của chân máy và sào trong đo đạc','<p>Chân máy và sào là phụ kiện tưởng chừng đơn giản nhưng ảnh hưởng trực tiếp đến độ ổn định và độ chính xác khi đo.</p><h4>Nội dung chính</h4><ul><li>Chân máy vững giúp hạn chế rung và lệch thiết bị.</li><li>Sào GNSS chuẩn giúp xác định đúng chiều cao ăng-ten.</li><li>Khóa chân và khớp nối cần chắc chắn, dễ điều chỉnh.</li><li>Chọn phụ kiện tương thích đầu ren 5/8 inch.</li></ul><p>Thiên Phú cung cấp chân máy, sào và phụ kiện trắc địa chính hãng.</p>','Tống Phú Quang','published','Vai trò của chân máy và sào trong đo đạc','Chân máy và sào ảnh hưởng trực tiếp đến độ ổn định, độ chính xác khi đo đạc. Cách chọn phụ kiện phù hợp.','vai-tro-cua-chan-may-va-sao-trong-do-dac','news','2026-10-21 14:25:19.649896','2026-10-21 14:25:19.649896',NULL),(_binary '�^\�/;~A�\�J-\�{','Cách kiểm tra và hiệu chuẩn máy toàn đạc tại công trường','<p>Kiểm tra nhanh trước khi đo giúp phát hiện sai lệch và đảm bảo kết quả công trình đáng tin cậy.</p><h4>Nội dung chính</h4><ul><li>Kiểm tra bọt thủy, trục ngắm và chế độ đo góc.</li><li>Đo kiểm tra một khoảng cách đã biết để đối chiếu sai số.</li><li>Vệ sinh ống kính và kiểm tra pin trước khi làm việc.</li><li>Đưa thiết bị đi hiệu chuẩn định kỳ theo khuyến nghị.</li></ul><p>Thiên Phú hỗ trợ kiểm tra và hiệu chuẩn máy toàn đạc tại xưởng.</p>','Tống Phú Quang','published','Cách kiểm tra và hiệu chuẩn máy toàn đạc tại công trường','Các bước kiểm tra nhanh và hiệu chuẩn máy toàn đạc tại công trường để đảm bảo kết quả đo tin cậy.','cach-kiem-tra-va-hieu-chuan-may-toan-dac-tai-cong-truong','news','2026-10-21 14:25:19.675891','2026-10-21 14:25:19.675891',NULL),(_binary '�^\�/Tו�\�dE	','GNSS RTK có cần trạm base? CORS/VRSNet là gì?','<p>Người mới sử dụng GNSS RTK thường thắc mắc có cần trạm base hay không và CORS/VRSNet hoạt động ra sao.</p><h4>Nội dung chính</h4><ul><li>Trạm base cho độ chính xác cao, phù hợp khu vực không có mạng.</li><li>CORS/VRSNet dùng trạm tham chiếu cố định, không cần dựng base.</li><li>Cần kiểm tra phạm vi phủ sóng và gói dịch vụ trước khi dùng.</li><li>Kết hợp cả hai giúp linh hoạt trong nhiều điều kiện công trình.</li></ul><p>Thiên Phú tư vấn phương án base hoặc CORS phù hợp với từng khu vực.</p>','Tống Phú Quang','published','GNSS RTK có cần trạm base? CORS/VRSNet là gì?','Giải đáp về trạm base, CORS và VRSNet khi sử dụng GNSS RTK, cách chọn phương án phù hợp.','gnss-rtk-co-can-tram-base-cors-vrsnet-la-gi','news','2026-10-21 14:25:19.700990','2026-10-21 14:25:19.700990',NULL),(_binary '�^\�/mtx�(�\Z#\"\Z�','Hướng dẫn đọc thông số kỹ thuật máy thủy bình','<p>Các thông số như độ phóng đại, sai số và phạm vi đo quyết định khả năng đáp ứng công việc của máy thủy bình.</p><h4>Nội dung chính</h4><ul><li>Độ phóng đại 20x đến 32x phù hợp nhu cầu đo đạc thông thường.</li><li>Sai số càng nhỏ càng phù hợp công trình yêu cầu cao.</li><li>Phạm vi đo ảnh hưởng đến khoảng cách đặt mia.</li><li>Chuẩn IP54 giúp máy chống bụi và nước nhẹ.</li></ul><p>Thiên Phú cung cấp máy thủy bình từ các thương hiệu Topcon, Sokkia, Leica, Nikon.</p>','Tống Phú Quang','published','Hướng dẫn đọc thông số kỹ thuật máy thủy bình','Cách đọc độ phóng đại, sai số, phạm vi đo và chuẩn bảo vệ của máy thủy bình.','huong-dan-doc-thong-so-ky-thuat-may-thuy-binh','news','2026-10-21 14:25:19.725279','2026-10-21 14:25:19.725279',NULL),(_binary '�^\�/�~��d���ID','Top 5 thương hiệu máy toàn đạc được tin dùng','<p>Thị trường máy toàn đạc có nhiều thương hiệu, mỗi thương hiệu có thế mạnh riêng về độ chính xác, độ bền và dịch vụ.</p><h4>Nội dung chính</h4><ul><li>Topcon: độ ổn định cao, phụ tùng phổ biến.</li><li>Sokkia: thao tác thân thiện, phù hợp khảo sát.</li><li>Leica: độ chính xác và công nghệ cao cấp.</li><li>Nikon: bền bỉ, dễ sử dụng.</li><li>Hi-Target và CHCNAV: lựa chọn tối ưu chi phí.</li></ul><p>Thiên Phú phân phối chính hãng các thương hiệu trên kèm bảo hành.</p>','Tống Phú Quang','published','Top 5 thương hiệu máy toàn đạc được tin dùng','Điểm qua Topcon, Sokkia, Leica, Nikon, Hi-Target và CHCNAV - những thương hiệu máy toàn đạc phổ biến.','top-5-thuong-hieu-may-toan-dac-duoc-tin-dung','news','2026-10-21 14:25:19.749935','2026-10-21 14:25:19.749935',NULL),(_binary '�^\�/�|��6m�	�g','Cách chọn máy đo khoảng cách laser cho kỹ sư xây dựng','<p>Máy đo khoảng cách laser phù hợp cho kỹ sư cần đo nhanh, chính xác và lưu dữ liệu tại công trình.</p><h4>Nội dung chính</h4><ul><li>Chọn tầm đo phù hợp: 50 đến 80 m cho nội thất, 100 đến 150 m cho công trình.</li><li>Ưu tiên sai số 1,5 mm với công việc yêu cầu cao.</li><li>Bluetooth giúp kết nối ứng dụng và xuất dữ liệu.</li><li>Kiểm tra chống bụi, nước và khả năng thay pin.</li></ul><p>Thiên Phú cung cấp máy đo khoảng cách laser chính hãng, bảo hành đầy đủ.</p>','Tống Phú Quang','published','Cách chọn máy đo khoảng cách laser cho kỹ sư xây dựng','Chọn máy đo khoảng cách laser theo tầm đo, sai số, kết nối Bluetooth và khả năng chống bụi nước.','cach-chon-may-do-khoang-cach-laser-cho-ky-su-xay-dung','news','2026-10-21 14:25:19.779300','2026-10-21 14:25:19.779300',NULL),(_binary '�^\�/�|��.\�\�','Ứng dụng GNSS RTK trong san lấp mặt bằng','<p>GNSS RTK giúp kiểm soát cao độ và khối lượng san lấp nhanh chóng, giảm sai sót so với phương pháp truyền thống.</p><h4>Nội